      if (t === 'África Tech') {
        return 'Empresas Tecnológicas de África: Naspers, Prosus, MTN Group, Vodacom, Safaricom, Jumia, Fawry, Flutterwave, Interswitch, OPay, Chipper Cash, Andela, Liquid Intelligent Technologies, Takealot';
      }
      return t;
    });

    const topicsString = expandedTopics.length > 0 ? expandedTopics.join(', ') : 'Temas Generales';

    // Check if customQuery is a URL
    const isUrl = customQuery ? /^(http|https):\/\/[^ "]+$/.test(customQuery.trim()) : false;

    let focusInstruction = '';
    let searchContext = '';

    if (isUrl) {
      // MODE: URL ANALYSIS
      focusInstruction = `
        🔴 MODO ANÁLISIS DE URL ACTIVO.
        El usuario ha proporcionado este ENLACE: "${customQuery}".
        TU TAREA ÚNICA: Accede al contenido de ese enlace (o busca información sobre esa URL específica usando Google Search si no puedes leerlo directamente) y REESCRIBE esa noticia siguiendo el formato editorial.
        IGNORA los temas seleccionados si no tienen relación con el enlace.
      `;
      searchContext = `Analiza a profundidad el contenido del enlace: ${customQuery}`;
    } else {
      // MODE: TOPIC SEARCH
      focusInstruction = customQuery ? `FOCUS ESPECÍFICO OBLIGATORIO EN: "${customQuery}"` : '';
      searchContext = `Busca en Google las noticias más recientes e impactantes de HOY. Temas: ${topicsString}. ${focusInstruction}`;
    }

    const styleInstructions = `
      1. **INICIO DIRECTO Y EXPLOSIVO:** PROHIBIDO usar frases de relleno como "Nos enteramos de...", "Les traemos...", "Atención gente...", "¿Sabían que...?". 
         - Empieza DIRECTAMENTE con el sujeto y la acción. 
         - Ejemplo MAL: "Amigos, nos enteramos de que Google lanzó..."
         - Ejemplo BIEN: "¡Google acaba de lanzar Gemini 3 y cambia todo el juego!"

      2. **Audiencia:** Mexicanos. Habla en plural ("nosotros") como medio, pero sé conciso.

      3. **DIETA DE EMOJIS:** Úsalos con moderación extrema. Máximo 2 o 3 por mensaje completo. Úsalos como "balas" o para resaltar algo muy grave, no para decorar.

      4. **Profundidad:** Desarrolla la noticia en 3 párrafos breves.
         - Párrafo 1: El hecho (Qué pasó).
         - Párrafo 2: El contexto (Por qué importa / Qué hay detrás).
         - Párrafo 3: La consecuencia (Qué va a pasar).

      5. **CIERRE LIMPIO (SIN REACCIONES):**
         - Termina la noticia con el punto final del tercer párrafo.
         - PROHIBIDO agregar preguntas ("¿Qué opinan?").
         - PROHIBIDO pedir reacciones ("Dale like si...").
         - El contenido debe hablar por sí mismo y ser informativo.

      6. **Tono:** Chisme Responsable pero SERIO en los datos. No uses jerga excesiva ("qué onda", "chale") a menos que la noticia sea muy ligera. Mantén la autoridad periodística pero con lenguaje sencillo.
    `;

    const systemPrompt = `
      Actúa como un editor experto de un canal de noticias de WhatsApp en México.

      OBJETIVO PRINCIPAL:
      Investigar, validar y generar contenido viral basado en la solicitud del usuario.

      CONTEXTO DE OPERACIÓN:
      ${focusInstruction}

      LÓGICA DE INVESTIGACIÓN:
      - Si es un ENLACE (URL): Extrae la información clave, verifica los hechos y transfórmalo al estilo del canal.
      - Si es BÚSQUEDA: Si hay un tema específico, esa es la prioridad. Si hay múltiples, busca intersecciones. Prioriza 'Última Hora'.

      HERRAMIENTA OBLIGATORIA:
      Usa Google Search para encontrar o validar la información.
      Si el usuario dio una URL, úsala como referencia principal y ponla en 'sourceUrl'.

      REGLAS DE ESTILO (CRÍTICO E INNEGOCIABLE):
      ${styleInstructions}

      REGLAS PARA EL PROMPT DE IMAGEN (ESTÁTICO):
      - El campo 'imagePrompt' DEBE estar estrictamente en INGLÉS.
      - Estilo: Photorealistic, Cinematic Lighting, 8k resolution, Highly Detailed, Press Photography style.

      REGLAS PARA EL PROMPT DE VIDEO (NUEVO - DINÁMICO):
      - El campo 'videoPrompt' DEBE estar estrictamente en INGLÉS.
      - Diseñado para IAs de video (Runway, Pika, Sora).
      - Estilo: Cinematic, Motion-focused.
      - INCLUYE MOVIMIENTOS DE CÁMARA: "Slow motion drone shot establishing...", "Close up pan...", "Time-lapse of...".
      - Describe la acción y la atmósfera (ej: "chaotic atmosphere", "futuristic glow", "serious news setting").

      REGLAS TÉCNICAS JSON (MUY IMPORTANTE):
      - Tu respuesta DEBE ser un JSON válido parseable.
      - CUIDADO con las comillas dobles (") dentro del texto. SIEMPRE escápalas con contra-barra (\\"). 
      - Usa comillas simples ('') dentro del texto preferiblemente.

      FORMATO DE SALIDA (JSON ARRAY ÚNICAMENTE):
      [
        {
          "category": "Categoría (Detectada automáticamente)",
          "title": "Título Corto",
          "whatsappBody": "Texto del mensaje optimizado para canal",
          "imagePrompt": "Prompt de imagen en INGLÉS",
          "videoPrompt": "Prompt de VIDEO en INGLÉS con movimientos de cámara",
          "sourceUrl": "URL proporcionada o encontrada"
        }
      ]
    `;

    const userPrompt = `
      EJECUTA LA OPERACIÓN:
      ${searchContext}

      Genera ${isUrl ? '1 propuesta optimizada basada en el enlace' : '3 a 5 propuestas detalladas'}. 
      Asegúrate de NO empezar con saludos ni frases de relleno.
      NO agregues ninguna llamada a la acción o pregunta al final.
    `;

    // Retry Logic for Generation
    let attempts = 0;
    const maxRetries = 3;

    while (attempts < maxRetries) {
      try {
        const client = this.getAiClient();

        const response = await client.models.generateContent({
          model: modelId,
          contents: [
            { role: 'model', parts: [{ text: systemPrompt }] },
            { role: 'user', parts: [{ text: userPrompt }] }
          ],
          config: {
            temperature: 0.85, 
            tools: [{ googleSearch: {} }]
          }
        });

        return this.parseResponse(response.text);

      } catch (error: any) {
        attempts++;
        const errorStr = JSON.stringify(error);
        console.warn(`generateNewsContent attempt ${attempts} failed.`);

        if (attempts < maxRetries && (errorStr.includes('429') || errorStr.includes('503') || errorStr.includes('RESOURCE_EXHAUSTED'))) {
           const waitTime = attempts * 3000;
           console.log(`Retrying generation in ${waitTime}ms...`);
           await this.delay(waitTime);
           continue;
        }
        console.error('Final error generating news:', error);
        throw error;
      }
    }
    throw new Error('Failed to generate content after multiple retries.');
  }

  private parseResponse(text: string | undefined): any[] {
     if (!text) throw new Error('La IA no generó texto.');

     console.log('Respuesta RAW Gemini:', text);

     let jsonString = text;
     const jsonMatch = text.match(/```json\s*([\s\S]*?)\s*```/) || text.match(/```\s*([\s\S]*?)\s*```/);
     if (jsonMatch) {
       jsonString = jsonMatch[1];
     }

     try {
       return JSON.parse(jsonString);
     } catch (e) {
       console.error('Error parseando JSON:', e);
       const arrayStart = jsonString.indexOf('[');
       const arrayEnd = jsonString.lastIndexOf(']');
       if (arrayStart !== -1 && arrayEnd !== -1) {
         const cleanJson = jsonString.substring(arrayStart, arrayEnd + 1);
         return JSON.parse(cleanJson);
       }
       throw new Error('No se pudo extraer JSON válido de la respuesta.');
     }
  }
}

import { Component, signal, inject, computed } from '@angular/core';
import { CommonModule } from '@angular/common';
import { GeminiService } from './services/gemini.service';
import { MatrixRainComponent } from './components/matrix-rain.component';

interface NewsItem {
  category: string;
  title: string;
  whatsappBody: string;
  imagePrompt: string;
  videoPrompt: string;
  sourceUrl?: string;
}

interface HeadlineItem {
  title: string;
  source: string;
  url: string;
  time: string;
}

@Component({
  selector: 'app-root',
  standalone: true,
  imports: [CommonModule, MatrixRainComponent],
  templateUrl: './app.component.html',
  styles: []
})
export class AppComponent {
  private geminiService = inject(GeminiService);

  // State
  isLoading = signal<boolean>(false);
  isLoadingHeadlines = signal<boolean>(false); // New distinct loading state for search
  generatedNews = signal<NewsItem[]>([]);
  fetchedHeadlines = signal<HeadlineItem[]>([]); // Lightweight headlines
  error = signal<string | null>(null);
  isOverloaded = signal<boolean>(false); 
  expandedPrompts = signal<Set<string>>(new Set());
  customQuery = signal<string>('');

  // Computed State for URL Detection
  isUrl = computed(() => {
    const query = this.customQuery().trim();
    return /^(http|https):\/\/[^ "]+$/.test(query);
  });

  // Dynamic Button Text
  searchButtonText = computed(() => {
    if (this.isLoading()) return 'Redactando...';
    if (this.isUrl()) return 'Analizar Enlace';
    return 'Iniciar Búsqueda';
  });

  // Available Topics
  availableTopics = [
    'Última Hora',
    'China Tech',
    'Estados Unidos Tech',
    'Europa Tech',
    'Latinoamérica Tech',
    'Corea del Sur Tech',
    'Japón Tech',
    'Rusia Tech',
    'Taiwán Tech',
    'Singapur Tech',
    'África Tech',
    'Ciencia',
    'Tecnología',
    'Guerra',
    'Economía',
    'Aranceles',
    'Criptomonedas',
    'México',
    'Estados Unidos',
    'Trump',
    'China',
    'Rusia',
    'Corea del Norte',
    'Irán',
    'Corea del Sur',
    'Japón',
    'OTAN',
    'Europa',
    'Latinoamérica',
    'Narcotráfico',
    'Inteligencia Artificial',
    'Computación Cuántica',
    'Física Cuántica'
  ];

  selectedTopics = signal<Set<string>>(new Set());

  toggleTopic(topic: string) {
    const current = new Set(this.selectedTopics());
    if (current.has(topic)) {
      current.delete(topic);
    } else {
      current.add(topic);
    }
    this.selectedTopics.set(current);
  }

  isTopicSelected(topic: string): boolean {
    return this.selectedTopics().has(topic);
  }

  selectAllTopics() {
    this.selectedTopics.set(new Set(this.availableTopics));
  }

  clearAllTopics() {
    this.selectedTopics.set(new Set());
  }

  togglePromptExpansion(key: string) {
    this.expandedPrompts.update(current => {
      const newSet = new Set(current);
      if (newSet.has(key)) {
        newSet.delete(key);
      } else {
        newSet.add(key);
      }
      return newSet;
    });
  }

  isPromptExpanded(key: string): boolean {
    return this.expandedPrompts().has(key);
  }

  onCustomQueryInput(event: Event) {
    const target = event.target as HTMLInputElement;
    this.customQuery.set(target.value);
  }

  // PHASE 1: SEARCH HEADLINES (LIGHTWEIGHT)
  async fetchHeadlines() {
    const topics = Array.from(this.selectedTopics());

    if (topics.length === 0) {
      this.error.set('Por favor selecciona al menos un tema para buscar noticias.');
      return;
    }

    this.isLoadingHeadlines.set(true);
    this.error.set(null);
    this.isOverloaded.set(false);
    this.fetchedHeadlines.set([]);
    this.generatedNews.set([]); // Clear previous heavy results

    try {
      const headlines = await this.geminiService.searchHeadlines(topics);
      this.fetchedHeadlines.set(headlines);
    } catch (err: any) {
      this.handleError(err);
    } finally {
      this.isLoadingHeadlines.set(false);
    }
  }

  // PHASE 2: GENERATE CONTENT FROM SELECTION (HEAVY)
  async selectHeadline(item: HeadlineItem) {
    // We populate the custom query with the URL so the standard logic can pick it up
    this.customQuery.set(item.url);
    // Trigger standard generation
    await this.generate();
  }

  async generate() {
    const topics = Array.from(this.selectedTopics());
    const query = this.customQuery().trim();

    if (topics.length === 0 && !query) {
      this.error.set('Por favor selecciona un tema o pega un enlace.');
      return;
    }

    this.isLoading.set(true);
    this.error.set(null);
    this.isOverloaded.set(false);
    this.generatedNews.set([]);
    // We do NOT clear fetchedHeadlines here, so the user can go back to the list

    try {
      const news = await this.geminiService.generateNewsContent(topics, query);
      this.generatedNews.set(news);
      // Optional: scroll to results could go here
    } catch (err: any) {
      this.handleError(err);
    } finally {
      this.isLoading.set(false);
    }
  }

  private handleError(err: any) {
    console.error("Error detected:", err);
    const errorMessage = JSON.stringify(err.message || err);

    if (
      errorMessage.includes('503') || 
      errorMessage.includes('429') || 
      errorMessage.includes('overloaded') || 
      errorMessage.includes('UNAVAILABLE') ||
      errorMessage.includes('Too Many Requests') ||
      errorMessage.includes('RESOURCE_EXHAUSTED')
    ) {
      this.isOverloaded.set(true);
    } else {
      this.error.set(err.message || 'Ocurrió un error. Intenta de nuevo.');
    }
  }

  copyToClipboard(text: string, id: string) {
    navigator.clipboard.writeText(text).then(() => {
      const btn = document.getElementById(id);
      if (btn) {
        const originalContent = btn.innerHTML;
        const originalClasses = btn.className;

        btn.innerHTML = `
          <svg xmlns="http://www.w3.org/2000/svg" class="h-5 w-5 text-emerald-400" fill="none" viewBox="0 0 24 24" stroke="currentColor">
             <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M5 13l4 4L19 7" />
          </svg>
          <span class="text-emerald-400">¡Copiado!</span>
        `;
        btn.className = `${originalClasses} bg-emerald-900/30 border-emerald-800`;

        setTimeout(() => {
           btn.innerHTML = originalContent;
           btn.className = originalClasses;
        }, 2000);
      }
    });
  }
}

import { Injectable } from '@angular/core';
import { GoogleGenAI } from '@google/genai';

// Declare process for TypeScript
declare const process: any;

@Injectable({
  providedIn: 'root'
})
export class GeminiService {
  private ai: GoogleGenAI | null = null;

  // ==================================================================================
  // 👇👇👇 PEGA TU API KEY AQUÍ ABAJO (DENTRO DE LAS COMILLAS) PARA ARREGLARLO 👇👇👇
  // ==================================================================================
  private readonly MANUAL_API_KEY = ''; 
  // ==================================================================================

  constructor() {}

  private getAiClient(): GoogleGenAI {
    if (this.ai) {
      return this.ai;
    }

    let apiKey = this.MANUAL_API_KEY;

    if (!apiKey) {
      try {
        // @ts-ignore
        const meta = import.meta as any;
        if (meta && meta.env) {
          apiKey = meta.env.VITE_API_KEY || meta.env.NG_APP_API_KEY || meta.env.API_KEY || '';
        }
      } catch (e) {}
      if (!apiKey) {
        try {
          if (typeof process !== 'undefined' && process.env) {
            apiKey = process.env.VITE_API_KEY || process.env.NEXT_PUBLIC_API_KEY || process.env.API_KEY || '';
          }
        } catch (e) {}
      }
    }

    if (!apiKey) {
      console.error('❌ ERROR CRÍTICO: No hay API KEY.');
      throw new Error(
        'Falta la API KEY. Por favor, abre "src/services/gemini.service.ts" y pega tu clave en la variable "MANUAL_API_KEY".'
      );
    } else {
      console.log('✅ API Key detectada correctamente.');
    }

    this.ai = new GoogleGenAI({ apiKey });
    return this.ai;
  }

  // MÉTODO LIGERO: Solo busca titulares y URLs
  async searchHeadlines(topics: string[]): Promise<any[]> {
    const modelId = 'gemini-2.5-flash';
    const topicsString = topics.length > 0 ? topics.join(', ') : 'Tecnología y Geopolítica Global';

    const systemPrompt = `
      Actúa como un agregador de noticias en tiempo real.
      TU OBJETIVO: Buscar noticias recientes (últimas 24h) sobre: ${topicsString}.
      FORMATO DE SALIDA: JSON Array estricto.
      CONTENIDO: Devuelve SOLO el título, la fuente y la URL. NO generes resúmenes. NO redactes nada.

      Output JSON format:
      [
        {
          "title": "Título impactante de la noticia",
          "source": "Nombre del Medio",
          "url": "Enlace directo",
          "time": "Hace X horas"
        }
      ]
    `;

    const userPrompt = `Encuentra 6 noticias importantes y variadas sobre ${topicsString} usando Google Search. Prioriza noticias de última hora.`;

    try {
      const client = this.getAiClient();
      const response = await client.models.generateContent({
        model: modelId,
        contents: [
          { role: 'model', parts: [{ text: systemPrompt }] },
          { role: 'user', parts: [{ text: userPrompt }] }
        ],
        config: {
          temperature: 0.3,
          tools: [{ googleSearch: {} }]
        }
      });

      return this.parseResponse(response.text);

    } catch (error) {
      console.error('Error buscando titulares:', error);
      throw error;
    }
  }

  // MÉTODO PESADO AHORA CON STREAMING: Genera el contenido viral completo
  async generateNewsContentStream(url: string, tone: string, formats: string[]) {
    const modelId = 'gemini-2.5-flash';

    const styleInstructions = `
      - INICIO DIRECTO Y EXPLOSIVO: Sin frases de relleno. Directo al sujeto y la acción.
      - AUDIENCIA: Mexicanos. Tono plural ("nosotros"). Conciso.
      - DIETA DE EMOJIS: Máximo 2-3 por mensaje. Solo para enfatizar.
      - PROFUNDIDAD: 3 párrafos breves (Qué, Por qué importa, Qué sigue).
      - CIERRE LIMPIO: Sin preguntas ni llamadas a la acción.
      - TONO BASE: "Chisme Responsable" pero con datos serios.
    `;

    const systemPrompt = `
      Actúas como un editor experto para un canal de noticias en México.
      Tu tarea es analizar una URL y generar contenido para múltiples plataformas.

      HERRAMIENTA OBLIGATORIA:
      Usa Google Search para analizar el contenido del enlace: "${url}".

      CONTROLES EDITORIALES DEL USUARIO:
      - Tono a aplicar: "${tone}"
      - Formatos a generar: ${JSON.stringify(formats)}

      INSTRUCCIONES DE TONO:
      - 'Directo y Serio': Fáctico, profesional, sin adornos.
      - 'Urgente / Alerta': Dramático, usa mayúsculas para énfasis, frases cortas e impactantes.
      - 'Análisis Profundo': Más detallado, explica el trasfondo y las implicaciones a largo plazo.

      INSTRUCCIONES DE FORMATO:
      - 'whatsapp': Sigue las reglas de estilo base.
      - 'twitter': Un post corto (<280 caracteres), con 2-3 hashtags relevantes.
      - 'email': Un newsletter con 'subject' (título atractivo) y 'body' (un poco más formal y elaborado que WhatsApp).

      REGLAS PARA PROMPTS DE IMAGEN Y VIDEO (EN INGLÉS):
      - imagePrompt: Photorealistic, Cinematic Lighting, 8k, Press Photography style.
      - videoPrompt: Cinematic, Motion-focused, incluye movimientos de cámara (ej: "Slow motion drone shot...", "Close up pan...").

      FORMATO DE SALIDA (JSON ÚNICO, NO ARRAY):
      Tu respuesta DEBE ser un único objeto JSON válido. Escapa las comillas dobles (\\") en el texto.
      Ejemplo de estructura (llena los campos que el usuario pida en 'formats'):
      {
        "category": "Categoría detectada",
        "title": "Título corto de la noticia",
        "sourceUrl": "${url}",
        "outputs": {
          "whatsapp": "...",
          "twitter": "...",
          "email": { "subject": "...", "body": "..." }
        },
        "imagePrompt": "Prompt en INGLÉS...",
        "videoPrompt": "Prompt de VIDEO en INGLÉS..."
      }
    `;

    const client = this.getAiClient();
    return client.models.generateContentStream({
      model: modelId,
      contents: [{ role: 'user', parts: [{ text: systemPrompt }] }],
      config: {
        temperature: 0.9,
        tools: [{ googleSearch: {} }]
      }
    });
  }

  // UTILITY: Parsea la respuesta de la IA
  parseResponse(text: string | undefined): any {
     if (!text) throw new Error('La IA no generó texto.');

     console.log('Respuesta RAW Gemini:', text);

     let jsonString = text;
     const jsonMatch = text.match(/```json\s*([\s\S]*?)\s*```/) || text.match(/```\s*([\s\S]*?)\s*```/);
     if (jsonMatch) {
       jsonString = jsonMatch[1];
     }

     try {
       return JSON.parse(jsonString);
     } catch (e) {
       console.error('Error parseando JSON:', e);
       const objStart = jsonString.indexOf('{');
       const objEnd = jsonString.lastIndexOf('}');
       if (objStart !== -1 && objEnd !== -1) {
         const cleanJson = jsonString.substring(objStart, objEnd + 1);
         return JSON.parse(cleanJson);
       }
       const arrayStart = jsonString.indexOf('[');
       const arrayEnd = jsonString.lastIndexOf(']');
       if (arrayStart !== -1 && arrayEnd !== -1) {
         const cleanJson = jsonString.substring(arrayStart, arrayEnd + 1);
         return JSON.parse(cleanJson);
       }
       throw new Error('No se pudo extraer JSON válido de la respuesta.');
     }
  }
}

