import { Component, signal, inject, computed, ChangeDetectionStrategy, effect } from '@angular/core';
import { CommonModule } from '@angular/common';
import { GeminiService } from './services/gemini.service';

interface NewsItem {
  category: string;
  title: string;
  sourceUrl?: string;
  outputs: {
    whatsapp?: string;
    twitter?: string;
    email?: {
      subject: string;
      body: string;
    };
  };
  imagePrompt: string;
  videoPrompt: string;
}

interface HeadlineItem {
  title: string;
