  // UTILITY: Parsea la respuesta de la IA
  parseResponse(text: string | undefined): any {
     if (!text) throw new Error('La IA no generó texto.');

     console.log('Respuesta RAW Gemini:', text);

     let jsonString = text;
     const jsonMatch = text.match(/```json\s*([\s\S]*?)\s*```/) || text.match(/```\s*([\s\S]*?)\s*```/);
     if (jsonMatch) {
       jsonString = jsonMatch[1];
     }

     try {
       return JSON.parse(jsonString);
     } catch (e) {
       console.error('Error parseando JSON:', e);
       const objStart = jsonString.indexOf('{');
       const objEnd = jsonString.lastIndexOf('}');
       if (objStart !== -1 && objEnd !== -1) {
         const cleanJson = jsonString.substring(objStart, objEnd + 1);
         try {
            return JSON.parse(cleanJson);
         } catch (e2) {
             console.error('Error parseando JSON extraído (objeto):', e2);
         }
       }
       const arrayStart = jsonString.indexOf('[');
       const arrayEnd = jsonString.lastIndexOf(']');
       if (arrayStart !== -1 && arrayEnd !== -1) {
         const cleanJson = jsonString.substring(arrayStart, arrayEnd + 1);
         try {
            return JSON.parse(cleanJson);
         } catch (e2) {
            console.error('Error parseando JSON extraído (array):', e2);
         }
       }
       throw new Error('No se pudo extraer JSON válido de la respuesta.');
     }
  }
}

import { Component, signal, inject, computed, ChangeDetectionStrategy, effect, WritableSignal } from '@angular/core';
import { CommonModule } from '@angular/common';
import { GeminiService } from './services/gemini.service';

interface NewsItem {
  category: string;
  title: string;
  sourceUrl?: string;
  outputs: {
    whatsapp?: string;
    twitter?: string;
    email?: {
      subject: string;
      body: string;
    };
  };
  imagePrompt: string;
  videoPrompt: string;
}

interface HeadlineItem {
  title: string;
  source: string;
  url: string;
  time: string;
}

@Component({
  selector: 'app-root',
  standalone: true,
  imports: [CommonModule],
  templateUrl: './app.component.html',
  styles: [],
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class AppComponent {
  private geminiService = inject(GeminiService);
  readonly isGeminiConfigured = this.geminiService.isConfigured.asReadonly();

  // State
  isLoading = signal<boolean>(false);
  isLoadingHeadlines = signal<boolean>(false);
  generatedNews = signal<NewsItem | null>(null);
  fetchedHeadlines = signal<HeadlineItem[]>([]);
  error = signal<string | null>(null);
  isOverloaded = signal<boolean>(false);
  streamingText = signal<string>('');

  // Editorial Controls State
  tones = ['Directo y Serio', 'Urgente / Alerta', 'Análisis Profundo'];
  selectedTone = signal('Directo y Serio');

  formats = ['WhatsApp', 'Twitter (X)', 'E-mail'];
  selectedFormats = signal<Set<string>>(new Set(['WhatsApp', 'Twitter (X)']));

  // UI State
  activeResultTab = signal('WhatsApp');
  manualUrlInput = signal<string>('');

  // Available Topics
  availableTopics = [
    'Última Hora', 'China Tech', 'Estados Unidos Tech', 'Europa Tech', 'Latinoamérica Tech',
    'Corea del Sur Tech', 'Japón Tech', 'Rusia Tech', 'Taiwán Tech', 'Singapur Tech', 'África Tech',
    'Ciencia', 'Tecnología', 'Guerra', 'Economía', 'Aranceles', 'Criptomonedas',
    'México', 'Estados Unidos', 'Trump', 'China', 'Rusia', 'Corea del Norte',
    'Irán', 'Corea del Sur', 'Japón', 'OTAN', 'Europa', 'Latinoamérica',
    'Narcotráfico', 'Inteligencia Artificial', 'Computación Cuántica', 'Física Cuántica'
  ];
  selectedTopics = signal<Set<string>>(new Set());

  constructor() {
    // Auto-select 'Última Hora' on init for convenience
    this.selectedTopics.set(new Set(['Última Hora']));
  }

  // --- Manual Input ---
  onManualUrlInput(event: Event) {
    this.manualUrlInput.set((event.target as HTMLInputElement).value);
  }

  // --- Topic Management ---
  toggleTopic(topic: string) {
    this.selectedTopics.update(current => {
      const newSet = new Set(current);
      newSet.has(topic) ? newSet.delete(topic) : newSet.add(topic);
      return newSet;
    });
  }

  isTopicSelected(topic: string): boolean {
    return this.selectedTopics().has(topic);
  }
  selectAllTopics = () => this.selectedTopics.set(new Set(this.availableTopics));
  clearAllTopics = () => this.selectedTopics.set(new Set());

  // --- Editorial Control Management ---
  selectTone = (tone: string) => this.selectedTone.set(tone);

  toggleFormat(format: string) {
    this.selectedFormats.update(current => {
      const newSet = new Set(current);
      newSet.has(format) ? newSet.delete(format) : newSet.add(format);
      return newSet;
    });
  }

  isFormatSelected(format: string): boolean {
    return this.selectedFormats().has(format);
  }

  // --- Core Actions ---
  async fetchHeadlines() {
    if (this.selectedTopics().size === 0) {
      this.error.set('Por favor selecciona al menos un tema.');
      return;
    }
    this.isLoadingHeadlines.set(true);
    this.error.set(null);
    this.isOverloaded.set(false);
    this.fetchedHeadlines.set([]);
    this.generatedNews.set(null);

    try {
      const headlines = await this.geminiService.searchHeadlines(Array.from(this.selectedTopics()));
      this.fetchedHeadlines.set(headlines);
    } catch (err: any) {
      this.handleError(err);
    } finally {
      this.isLoadingHeadlines.set(false);
    }
  }

  async generateFromManualInput() {
    const url = this.manualUrlInput().trim();
    if (!url) {
      this.error.set('Por favor, introduce un enlace para analizar.');
      return;
    }

    // Basic URL validation. Allows for URLs without http protocol.
    // FIX: The original regex literal was causing a "Cannot find name '$'" error, likely due to a parser bug with its complex structure.
    // Replaced with `new RegExp()` and a simplified, more robust pattern for URL validation.
    const urlPattern = new RegExp('^(https?://)?([\\da-z.-]+)\\.([a-z.]{2,6})([/\\w .-]*)/?$');

    if (!urlPattern.test(url)) {
      this.error.set('El enlace introducido no parece ser una URL válida.');
      return;
    }

    await this.generate(url);
    this.manualUrlInput.set(''); 
  }

  async generate(url: string) {
    if (this.selectedFormats().size === 0) {
      this.error.set('Por favor selecciona al menos un formato de salida.');
      return;
    }
    this.isLoading.set(true);
    this.error.set(null);
    this.isOverloaded.set(false);
    this.generatedNews.set(null);
    this.streamingText.set('');

    try {
      const stream = await this.geminiService.generateNewsContentStream(
        url,
        this.selectedTone(),
        Array.from(this.selectedFormats())
      );

      let accumulatedJson = '';
      for await (const chunk of stream) {
        accumulatedJson += chunk.text;
        this.streamingText.set(accumulatedJson);
      }

      const finalResult = this.geminiService.parseResponse(accumulatedJson);
      this.generatedNews.set(finalResult);

    } catch (err: any) {
      this.handleError(err);
    } finally {
      this.isLoading.set(false);
      this.streamingText.set('');
    }
  }

  private handleError(err: any) {
    console.error("Error detectado:", err);
    const errorMessage = JSON.stringify(err.message || err);

    if (errorMessage.includes('429') || errorMessage.includes('RESOURCE_EXHAUSTED')) {
      this.isOverloaded.set(true);
      this.error.set('Límite de cuota alcanzado. Intenta más tarde.');
    } else {
      this.error.set(err.message || 'Ocurrió un error al generar. Revisa la consola.');
    }
  }

  // --- UI and Utility ---
  doesFormatExist(news: NewsItem | null, format: string): boolean {
    if (!news || !news.outputs) {
      return false;
    }
    const key = format.split(' ')[0].toLowerCase().replace('-', '') as keyof NewsItem['outputs'];
    return !!news.outputs[key];
  }

  copyToClipboard(text: string | undefined) {
    if (!text) return;
    navigator.clipboard.writeText(text);
  }

  getActiveTabText(): string {
    const news = this.generatedNews();
    if (!news) return '';

    switch(this.activeResultTab()) {
      case 'WhatsApp': return news.outputs.whatsapp || '';
      case 'Twitter (X)': return news.outputs.twitter || '';
      case 'E-mail': return `Asunto: ${news.outputs.email?.subject}\n\n${news.outputs.email?.body}`;
      default: return '';
    }
  }
}

