    const modelId = 'gemini-2.5-flash';

    const systemInstruction = `
      Actúas como un editor experto para un canal de noticias en México.
      Tu tarea es analizar una URL proporcionada por el usuario y generar contenido para múltiples plataformas según sus especificaciones.

