import { Injectable, signal } from '@angular/core';
import { GoogleGenAI } from '@google/genai';

// Declare process for TypeScript
declare const process: any;

@Injectable({
  providedIn: 'root'
})
export class GeminiService {
  private ai: GoogleGenAI | undefined;
  isConfigured = signal<boolean>(false);

  constructor() {
    // FIX: Use `API_KEY` as per the coding guidelines.
    const apiKey = process?.env?.API_KEY;
    if (apiKey) {
      this.ai = new GoogleGenAI({ apiKey: apiKey });
      this.isConfigured.set(true);
    } else {
      // FIX: Update error message to reflect the correct environment variable.
      console.error('CRITICAL: Google AI API key is not configured. Please set the `API_KEY` environment variable in your deployment platform.');
      this.isConfigured.set(false);
    }
  }

  private getAiClient(): GoogleGenAI {
    if (!this.ai) {
      throw new Error('GeminiService is not configured. API Key is missing.');
    }
    return this.ai;
  }

  // MÉTODO LIGERO: Solo busca titulares y URLs
  async searchHeadlines(topics: string[]): Promise<any[]> {
    const modelId = 'gemini-2.5-flash';
    const topicsString = topics.length > 0 ? topics.join(', ') : 'Tecnología y Geopolítica Global';

    const systemInstruction = `
      Actúa como un agregador de noticias global en tiempo real.
      TU OBJETIVO: 
      1. BUSCAR noticias recientes (últimas 24h) sobre: ${topicsString}. Busca en fuentes de todo el mundo, sin importar el idioma original (chino, ruso, japonés, coreano, inglés, etc.).
      2. TRADUCIR los titulares encontrados al español para el resultado final.

      FORMATO DE SALIDA: JSON Array estricto. El campo "title" DEBE contener el titular traducido al español.
      CONTENIDO: Devuelve SOLO el título traducido, la fuente original y la URL. NO generes resúmenes.

      Output JSON format:
      [
        {
          "title": "Título impactante de la noticia (YA TRADUCIDO AL ESPAÑOL)",
          "source": "Nombre del Medio Original (ej. Xinhua, Nikkei)",
          "url": "Enlace directo",
          "time": "Hace X horas"
        }
      ]
    `;

    const userPrompt = `Encuentra 6 noticias internacionales importantes y variadas sobre ${topicsString} usando Google Search. Traduce los titulares al español para la respuesta. Prioriza noticias de última hora de fuentes diversas (Asia, Europa, América, etc.).`;

    try {
      const client = this.getAiClient();
      const response = await client.models.generateContent({
        model: modelId,
        contents: userPrompt,
        config: {
          systemInstruction,
          temperature: 0.3,
          tools: [{ googleSearch: {} }]
        }
      });

      return this.parseResponse(response.text);

    } catch (error) {
      console.error('Error buscando titulares:', error);
      throw error;
    }
  }

  // MÉTODO PESADO AHORA CON STREAMING: Genera el contenido viral completo
  async generateNewsContentStream(url: string, tone: string, formats: string[]) {
    const modelId = 'gemini-2.5-flash';

    const systemInstruction = `
      Actúas como un editor experto para un canal de noticias en México.
      Tu tarea es analizar una URL proporcionada por el usuario y generar contenido para múltiples plataformas según sus especificaciones.

      HERRAMIENTA OBLIGATORIA:
      Usa Google Search para analizar el contenido del enlace que te da el usuario. Aunque la fuente original esté en otro idioma, TODO tu texto de salida debe ser en ESPAÑOL.

      INSTRUCCIONES DE TONO (SEGÚN PETICIÓN DEL USUARIO):
      - 'Directo y Serio': Fáctico, profesional, sin adornos.
      - 'Urgente / Alerta': Dramático, usa mayúsculas para énfasis, frases cortas e impactantes.
      - 'Análisis Profundo': Más detallado, explica el trasfondo y las implicaciones a largo plazo.

      INSTRUCCIONES DE FORMATO (SEGÚN PETICIÓN DEL USUARIO):
      - 'whatsapp': Sigue las reglas de estilo base.
      - 'twitter': Un post corto (<280 caracteres), con 2-3 hashtags relevantes.
      - 'email': Un newsletter con 'subject' (título atractivo) y 'body' (un poco más formal y elaborado que WhatsApp).

      REGLAS DE ESTILO BASE (para WhatsApp y como guía general):
      - INICIO DIRECTO Y EXPLOSIVO: Sin frases de relleno. Directo al sujeto y la acción.
      - AUDIENCIA: Mexicanos. Tono plural ("nosotros"). Conciso.
      - DIETA DE EMOJIS: Máximo 2-3 por mensaje. Solo para enfatizar.
      - PROFUNDIDAD: 3 párrafos breves (Qué, Por qué importa, Qué sigue).
      - CIERRE LIMPIO: Sin preguntas ni llamadas a la acción.
      - TONO BASE: "Chisme Responsable" pero con datos serios.

      REGLAS PARA PROMPTS DE IMAGEN Y VIDEO (DEBEN ESTAR EN INGLÉS):
      - imagePrompt: Photorealistic, Cinematic Lighting, 8k, Press Photography style.
      - videoPrompt: Cinematic, Motion-focused, incluye movimientos de cámara (ej: "Slow motion drone shot...", "Close up pan...").

      FORMATO DE SALIDA (JSON ÚNICO, NO ARRAY):
      Tu respuesta DEBE ser un único objeto JSON válido. Escapa las comillas dobles (\\") en el texto si es necesario.
      La estructura es:
      {
        "category": "Categoría detectada (en español)",
        "title": "Título corto de la noticia (en español)",
        "sourceUrl": "la URL original que te dio el usuario",
        "outputs": {
          "whatsapp": "...",
          "twitter": "...",
          "email": { "subject": "...", "body": "..." }
        },
        "imagePrompt": "Prompt en INGLÉS...",
        "videoPrompt": "Prompt de VIDEO en INGLÉS..."
      }
    `;

    const userPrompt = `Analiza la URL "${url}", aplica el tono "${tone}" y genera contenido para los siguientes formatos: ${formats.join(', ')}.`;

    const client = this.getAiClient();
    return client.models.generateContentStream({
      model: modelId,
      contents: userPrompt,
      config: {
        systemInstruction,
        temperature: 0.9,
        tools: [{ googleSearch: {} }]
      }
    });
  }

  // UTILITY: Parsea la respuesta de la IA
  parseResponse(text: string | undefined): any {
     if (!text) throw new Error('La IA no generó texto.');

     console.log('Respuesta RAW Gemini:', text);

     let jsonString = text;
     const jsonMatch = text.match(/```json\s*([\s\S]*?)\s*```/) || text.match(/```\s*([\s\S]*?)\s*```/);
     if (jsonMatch) {
       jsonString = jsonMatch[1];
     }

     try {
       return JSON.parse(jsonString);
     } catch (e) {
       console.error('Error parseando JSON:', e);
       const objStart = jsonString.indexOf('{');
       const objEnd = jsonString.lastIndexOf('}');
       if (objStart !== -1 && objEnd !== -1) {
         const cleanJson = jsonString.substring(objStart, objEnd + 1);
         try {
            return JSON.parse(cleanJson);
         } catch (e2) {
             console.error('Error parseando JSON extraído (objeto):', e2);
         }
       }
       const arrayStart = jsonString.indexOf('[');
       const arrayEnd = jsonString.lastIndexOf(']');
       if (arrayStart !== -1 && arrayEnd !== -1) {
         const cleanJson = jsonString.substring(arrayStart, arrayEnd + 1);
         try {
            return JSON.parse(cleanJson);
         } catch (e2) {
            console.error('Error parseando JSON extraído (array):', e2);
         }
       }
       throw new Error('No se pudo extraer JSON válido de la respuesta.');
     }
  }
}

import { Component, signal, inject, computed, ChangeDetectionStrategy, effect, WritableSignal } from '@angular/core';
import { CommonModule } from '@angular/common';
import { GeminiService } from './services/gemini.service';

interface NewsItem {
  category: string;
  title: string;
  sourceUrl?: string;
  outputs: {
    whatsapp?: string;
    twitter?: string;
    email?: {
      subject: string;
      body: string;
    };
  };
  imagePrompt: string;
  videoPrompt: string;
}

interface HeadlineItem {
  title: string;
  source: string;
  url: string;
  time: string;
}

@Component({
  selector: 'app-root',
  standalone: true,
  imports: [CommonModule],
  templateUrl: './app.component.html',
  styles: [],
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class AppComponent {
  private geminiService = inject(GeminiService);
  readonly isGeminiConfigured = this.geminiService.isConfigured.asReadonly();

  // State
  isLoading = signal<boolean>(false);
  isLoadingHeadlines = signal<boolean>(false);
  generatedNews = signal<NewsItem | null>(null);
  fetchedHeadlines = signal<HeadlineItem[]>([]);
  error = signal<string | null>(null);
  isOverloaded = signal<boolean>(false);
  streamingText = signal<string>('');

  // Editorial Controls State
  tones = ['Directo y Serio', 'Urgente / Alerta', 'Análisis Profundo'];
  selectedTone = signal('Directo y Serio');

  formats = ['WhatsApp', 'Twitter (X)', 'E-mail'];
  selectedFormats = signal<Set<string>>(new Set(['WhatsApp', 'Twitter (X)']));

  // UI State
  activeResultTab = signal('WhatsApp');
  manualUrlInput = signal<string>('');

  // Infographic State
  infographicState = signal<'idle' | 'loading' | 'success' | 'error'>('idle');
  infographicUrl = signal<string | null>(null);

  // Available Topics
  availableTopics = [
    'Última Hora', 'China Tech', 'Estados Unidos Tech', 'Europa Tech', 'Latinoamérica Tech',
    'Corea del Sur Tech', 'Japón Tech', 'Rusia Tech', 'Taiwán Tech', 'Singapur Tech', 'África Tech',
    'Ciencia', 'Tecnología', 'Guerra', 'Economía', 'Aranceles', 'Criptomonedas',
    'México', 'Estados Unidos', 'Trump', 'China', 'Rusia', 'Corea del Norte',
    'Irán', 'Corea del Sur', 'Japón', 'OTAN', 'Europa', 'Latinoamérica',
    'Narcotráfico', 'Inteligencia Artificial', 'Computación Cuántica', 'Física Cuántica', 'Deploy Test'
  ];
  selectedTopics = signal<Set<string>>(new Set());

  constructor() {
    // Auto-select 'Última Hora' on init for convenience
    this.selectedTopics.set(new Set(['Última Hora']));
  }

  // --- Manual Input ---
  onManualUrlInput(event: Event) {
    this.manualUrlInput.set((event.target as HTMLInputElement).value);
  }

  // --- Topic Management ---
  toggleTopic(topic: string) {
    this.selectedTopics.update(current => {
      const newSet = new Set(current);
      newSet.has(topic) ? newSet.delete(topic) : newSet.add(topic);
      return newSet;
    });
  }

  isTopicSelected(topic: string): boolean {
    return this.selectedTopics().has(topic);
  }
  selectAllTopics = () => this.selectedTopics.set(new Set(this.availableTopics));
  clearAllTopics = () => this.selectedTopics.set(new Set());

  // --- Editorial Control Management ---
  selectTone = (tone: string) => this.selectedTone.set(tone);

  toggleFormat(format: string) {
    this.selectedFormats.update(current => {
      const newSet = new Set(current);
      // FIX: Corrected variable from `topic` to `format`.
      newSet.has(format) ? newSet.delete(format) : newSet.add(format);
      return newSet;
    });
  }

  isFormatSelected(format: string): boolean {
    return this.selectedFormats().has(format);
  }

  // --- Core Actions ---
  async fetchHeadlines() {
    if (this.selectedTopics().size === 0) {
      this.error.set('Por favor selecciona al menos un tema.');
      return;
    }
    this.isLoadingHeadlines.set(true);
    this.error.set(null);
    this.isOverloaded.set(false);
    this.fetchedHeadlines.set([]);
    this.generatedNews.set(null);

    try {
      const headlines = await this.geminiService.searchHeadlines(Array.from(this.selectedTopics()));
      this.fetchedHeadlines.set(headlines);
    } catch (err: any) {
      this.handleError(err);
    } finally {
      this.isLoadingHeadlines.set(false);
    }
  }

  async generateFromManualInput() {
    const url = this.manualUrlInput().trim();
    if (!url) {
      this.error.set('Por favor, introduce un enlace para analizar.');
      return;
    }

    // Basic URL validation. Allows for URLs without http protocol.
    const urlPattern = new RegExp('^(https?://)?([\\da-z.-]+)\\.([a-z.]{2,6})([/\\w .-]*)/?$');

    if (!urlPattern.test(url)) {
      this.error.set('El enlace introducido no parece ser una URL válida.');
      return;
    }

    await this.generate(url);
    this.manualUrlInput.set(''); 
  }

  async generate(url: string) {
    if (this.selectedFormats().size === 0) {
      this.error.set('Por favor selecciona al menos un formato de salida.');
      return;
    }
    this.isLoading.set(true);
    this.error.set(null);
    this.isOverloaded.set(false);
    this.generatedNews.set(null);
    this.streamingText.set('');

    try {
      const stream = await this.geminiService.generateNewsContentStream(
        url,
        this.selectedTone(),
        Array.from(this.selectedFormats())
      );

      let accumulatedJson = '';
      for await (const chunk of stream) {
        accumulatedJson += chunk.text;
        this.streamingText.set(accumulatedJson);
      }

      const finalResult = this.geminiService.parseResponse(accumulatedJson);
      this.generatedNews.set(finalResult);

    } catch (err: any) {
      this.handleError(err);
    } finally {
      this.isLoading.set(false);
      this.streamingText.set('');
    }
  }

  private handleError(err: any) {
    console.error("Error detectado:", err);
    const errorMessage = JSON.stringify(err.message || err);

    if (errorMessage.includes('429') || errorMessage.includes('RESOURCE_EXHAUSTED')) {
      this.isOverloaded.set(true);
      this.error.set('Límite de cuota alcanzado. Intenta más tarde.');
    } else {
      this.error.set(err.message || 'Ocurrió un error al generar. Revisa la consola.');
    }
  }

  // --- Infographic Generation ---
  async generateInfographic(news: NewsItem) {
    this.infographicState.set('loading');
    this.infographicUrl.set(null);

    // Simulate API call to "nano banaba"
    await new Promise(resolve => setTimeout(resolve, 2500));

    // Use a placeholder image service for the infographic
    const placeholderUrl = `https://picsum.photos/seed/${encodeURIComponent(news.title)}/800/1200`;
    this.infographicUrl.set(placeholderUrl);
    this.infographicState.set('success');
  }

  closeInfographic() {
    this.infographicState.set('idle');
    this.infographicUrl.set(null);
  }

  // --- UI and Utility ---
  doesFormatExist(news: NewsItem | null, format: string): boolean {
    if (!news || !news.outputs) {
      return false;
    }
    const key = format.split(' ')[0].toLowerCase().replace('-', '') as keyof NewsItem['outputs'];
    return !!news.outputs[key];
  }

  copyToClipboard(text: string | undefined) {
    if (!text) return;
    navigator.clipboard.writeText(text);
  }

  getActiveTabText(): string {
    const news = this.generatedNews();
    if (!news) return '';

    switch(this.activeResultTab()) {
      case 'WhatsApp': return news.outputs.whatsapp || '';
      case 'Twitter (X)': return news.outputs.twitter || '';
      case 'E-mail': return `Asunto: ${news.outputs.email?.subject}\n\n${news.outputs.email?.body}`;
      default: return '';
    }
  }
}

