    if (errorMessage.includes('429') || errorMessage.includes('RESOURCE_EXHAUSTED') || errorMessage.includes('quota')) {
      this.isOverloaded.set(true);
      this.error.set('Límite de peticiones gratuitas alcanzado. La red está sobrecargada. Por favor, espera un momento antes de volver a intentarlo.');
    } else {
      this.error.set(errorMessage || 'Ocurrió un error al generar. Revisa la consola.');
    }
  }

  // --- Visualization Generation ---
  async visualizePromptHandler(news: NewsItem) {
    this.visualizationState.set('loading');
    this.visualizationText.set(null);

    try {
      const description = await this.geminiService.visualizePrompt(news.imagePrompt);
      this.visualizationText.set(description);
      this.visualizationState.set('success');
    } catch (err) {
      console.error('Failed to visualize prompt:', err);
      this.visualizationState.set('error');
      this.handleError(err);
    }
  }

  closeVisualization() {
    this.visualizationState.set('idle');
    this.visualizationText.set(null);
  }

  // --- UI and Utility ---
  doesFormatExist(news: NewsItem | null, format: string): boolean {
    if (!news || !news.outputs) {
      return false;
    }
    const key = format.split(' ')[0].toLowerCase().replace('-', '') as keyof NewsItem['outputs'];
    return !!news.outputs[key];
  }

  copyToClipboard(text: string | undefined) {
    if (!text) return;
    navigator.clipboard.writeText(text);
  }

  getActiveTabText(): string {
    const news = this.generatedNews();
    if (!news) return '';

    switch(this.activeResultTab()) {
      case 'WhatsApp': return news.outputs.whatsapp || '';
      case 'Twitter (X)': return news.outputs.twitter || '';
      case 'E-mail': return `Asunto: ${news.outputs.email?.subject}\n\n${news.outputs.email?.body}`;
      default: return '';
    }
  }
}

import { Injectable, signal } from '@angular/core';
import { GoogleGenAI } from '@google/genai';

// Declare process for TypeScript
declare const process: any;

@Injectable({
