import { Injectable, signal } from '@angular/core';
import { GoogleGenAI } from '@google/genai';

// Declare process for TypeScript
declare const process: any;

@Injectable({
  providedIn: 'root'
})
export class GeminiService {
  private ai: GoogleGenAI | undefined;
  isConfigured = signal<boolean>(false);
  private pollingInterval: any = null;

  constructor() {
    // Initial check for the API key.
    this.checkApiKey();

    // If not configured, start polling. This is for environments like AI Studio
    // where the key is injected asynchronously after user selects it.
    if (!this.isConfigured()) {
      this.startPollingForKey();
    }
  }

  private checkApiKey(): void {
    const win = window as any;
    let apiKey: string | undefined;

    // Be extra defensive and check multiple possible locations.
    if (win.process?.env?.API_KEY) {
        apiKey = win.process.env.API_KEY;
    } else if (typeof process !== 'undefined' && process?.env?.API_KEY) {
        apiKey = process.env.API_KEY;
    }

    if (apiKey && typeof apiKey === 'string' && apiKey.length > 0 && !this.isConfigured()) {
        console.log('API Key detected. Configuring Gemini Service...');
        try {
            this.ai = new GoogleGenAI({ apiKey: apiKey });
            this.isConfigured.set(true);
            this.stopPollingForKey();
            console.log('Gemini Service configured successfully.');
        } catch (e) {
            console.error('Failed to initialize GoogleGenAI with the detected API key:', e);
            // The app will remain in the "not configured" state.
        }
    }
  }

  private startPollingForKey(): void {
    if (this.pollingInterval) return;
    console.log('API Key not present on initial load. Polling for asynchronous injection...');
    this.pollingInterval = setInterval(() => this.checkApiKey(), 500);
  }

  private stopPollingForKey(): void {
    if (this.pollingInterval) {
      console.log('Stopping API Key polling.');
      clearInterval(this.pollingInterval);
      this.pollingInterval = null;
    }
  }

  private getAiClient(): GoogleGenAI {
    if (!this.ai) {
      throw new Error('GeminiService is not configured. API Key is missing.');
    }
    return this.ai;
  }

  // MÉTODO LIGERO: Solo busca titulares y URLs
