      }
    });
  }

  // Generate a vivid description from an image prompt
  async visualizePrompt(prompt: string): Promise<string> {
    const modelId = 'gemini-2.5-flash';
    const systemInstruction = `
      You are a world-class film director and cinematographer. Your task is to read an image prompt and write a vivid, detailed, and atmospheric description of the resulting scene. 
      Focus on camera angles, lighting, mood, textures, colors, and the emotions of the scene. 
      The output MUST be in Spanish. Do not describe what you are, just the scene.
    `;
    const userPrompt = `Describe la siguiente escena: "${prompt}"`;

    try {
      const client = this.getAiClient();
      const response = await client.models.generateContent({
        model: modelId,
        contents: userPrompt,
        config: { systemInstruction, temperature: 0.8 }
      });
      return response.text;
    } catch (error) {
      console.error('Error visualizando el prompt:', error);
      throw error;
    }
  }

  // UTILITY: Parsea la respuesta de la IA
  parseResponse(text: string | undefined): any {
     if (!text) throw new Error('La IA no generó texto.');

     console.log('Respuesta RAW Gemini:', text);

     let jsonString = text;
     const jsonMatch = text.match(/```json\s*([\s\S]*?)\s*```/) || text.match(/```\s*([\s\S]*?)\s*```/);
     if (jsonMatch) {
       jsonString = jsonMatch[1];
     }

     // Function to clean common JSON errors like trailing commas.
     const clean = (str: string) => str.trim().replace(/,\s*([}\]])/g, '$1');

     try {
       return JSON.parse(clean(jsonString));
     } catch (e) {
       console.error('Error parseando JSON:', e);

       // Fallback for objects
       const objStart = jsonString.indexOf('{');
       const objEnd = jsonString.lastIndexOf('}');
       if (objStart !== -1 && objEnd > objStart) {
         const extractedObj = jsonString.substring(objStart, objEnd + 1);
         try {
            return JSON.parse(clean(extractedObj));
         } catch (e2) {
             console.error('Error parseando JSON extraído (objeto):', e2);
         }
       }

       // Fallback for arrays
       const arrayStart = jsonString.indexOf('[');
       const arrayEnd = jsonString.lastIndexOf(']');
       if (arrayStart !== -1 && arrayEnd > arrayStart) {
         const extractedArray = jsonString.substring(arrayStart, arrayEnd + 1);
         try {
            return JSON.parse(clean(extractedArray));
         } catch (e2) {
            console.error('Error parseando JSON extraído (array):', e2);
         }
       }

       throw new Error('No se pudo extraer JSON válido de la respuesta.');
     }
  }
