  // UTILITY: Parsea la respuesta de la IA
  parseResponse(text: string | undefined): any {
     if (!text) throw new Error('La IA no generó texto.');

     console.log('Respuesta RAW Gemini:', text);

     let jsonString = text;
     const jsonMatch = text.match(/```json\s*([\s\S]*?)\s*```/) || text.match(/```\s*([\s\S]*?)\s*```/);
     if (jsonMatch) {
       jsonString = jsonMatch[1];
     }

     // Function to clean common JSON errors like trailing commas.
     const clean = (str: string) => str.trim().replace(/,\s*([}\]])/g, '$1');

     try {
       return JSON.parse(clean(jsonString));
     } catch (e) {
       console.error('Error parseando JSON:', e);

       // Fallback for objects
       const objStart = jsonString.indexOf('{');
       const objEnd = jsonString.lastIndexOf('}');
       if (objStart !== -1 && objEnd > objStart) {
         const extractedObj = jsonString.substring(objStart, objEnd + 1);
         try {
            return JSON.parse(clean(extractedObj));
         } catch (e2) {
             console.error('Error parseando JSON extraído (objeto):', e2);
         }
       }

       // Fallback for arrays
       const arrayStart = jsonString.indexOf('[');
       const arrayEnd = jsonString.lastIndexOf(']');
       if (arrayStart !== -1 && arrayEnd > arrayStart) {
         const extractedArray = jsonString.substring(arrayStart, arrayEnd + 1);
         try {
            return JSON.parse(clean(extractedArray));
         } catch (e2) {
            console.error('Error parseando JSON extraído (array):', e2);
         }
       }

       throw new Error('No se pudo extraer JSON válido de la respuesta.');
     }
  }
}

import { Component, signal, inject, computed, ChangeDetectionStrategy, effect, WritableSignal } from '@angular/core';
import { CommonModule } from '@angular/common';
import { GeminiService } from './services/gemini.service';
import { MatrixRainComponent } from './components/matrix-rain.component';

interface NewsItem {
  category: string;
  title: string;
  sourceUrl?: string;
  whatsappContent: string;
  imagePrompt: string;
  videoPrompt: string;
}

interface HeadlineItem {
  title: string;
  source: string;
  url: string;
  time: string;
}

@Component({
  selector: 'app-root',
  standalone: true,
  imports: [CommonModule, MatrixRainComponent],
  templateUrl: './app.component.html',
  styles: [],
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class AppComponent {
  private geminiService = inject(GeminiService);
  readonly isGeminiConfigured = this.geminiService.isConfigured.asReadonly();

  // State
  isLoading = signal<boolean>(false);
  isLoadingHeadlines = signal<boolean>(false);
  generatedNews = signal<NewsItem | null>(null);
  fetchedHeadlines = signal<HeadlineItem[]>([]);
  error = signal<string | null>(null);
  isOverloaded = signal<boolean>(false);
  streamingText = signal<string>('');

  // UI State
  manualUrlInput = signal<string>('');
  isBooting = signal<boolean>(true);

  // Visualization State
  visualizationState = signal<'idle' | 'loading' | 'success' | 'error'>('idle');
  visualizationText = signal<string | null>(null);

  // Available Topics
  availableTopics = [
    'Última Hora', 'China Tech', 'Estados Unidos Tech', 'Europa Tech', 'Latinoamérica Tech',
    'Corea del Sur Tech', 'Japón Tech', 'Rusia Tech', 'Taiwán Tech', 'Singapur Tech', 'África Tech',
    'Ciencia', 'Tecnología', 'Guerra', 'Economía', 'Aranceles', 'Criptomonedas',
    'México', 'Estados Unidos', 'Trump', 'China', 'Rusia', 'Corea del Norte',
    'Irán', 'Corea del Sur', 'Japón', 'OTAN', 'Europa', 'Latinoamérica',
    'Narcotráfico', 'Inteligencia Artificial', 'Computación Cuántica', 'Física Cuántica', 'Deploy Test'
  ];
  selectedTopics = signal<Set<string>>(new Set());

  constructor() {
    // Auto-select 'Última Hora' on init for convenience
    this.selectedTopics.set(new Set(['Última Hora']));
  }

  // --- Boot Sequence ---
  onBootComplete() {
    this.isBooting.set(false);
  }

  // --- Manual Input ---
  onManualUrlInput(event: Event) {
    this.manualUrlInput.set((event.target as HTMLInputElement).value);
  }

  // --- Topic Management ---
  toggleTopic(topic: string) {
    this.selectedTopics.update(current => {
      const newSet = new Set(current);
      newSet.has(topic) ? newSet.delete(topic) : newSet.add(topic);
      return newSet;
    });
  }

  isTopicSelected(topic: string): boolean {
    return this.selectedTopics().has(topic);
  }
  selectAllTopics = () => this.selectedTopics.set(new Set(this.availableTopics));
  clearAllTopics = () => this.selectedTopics.set(new Set());

  // --- Core Actions ---
  async fetchHeadlines() {
    if (this.selectedTopics().size === 0) {
      this.error.set('Por favor selecciona al menos un tema.');
      return;
    }
    this.isLoadingHeadlines.set(true);
    this.error.set(null);
    this.isOverloaded.set(false);
    this.fetchedHeadlines.set([]);
    this.generatedNews.set(null);

    try {
      const headlines = await this.geminiService.searchHeadlines(Array.from(this.selectedTopics()));
      this.fetchedHeadlines.set(headlines);
    } catch (err: any) {
      this.handleError(err);
    } finally {
      this.isLoadingHeadlines.set(false);
    }
  }

  async generateFromManualInput() {
    const url = this.manualUrlInput().trim();
    if (!url) {
      this.error.set('Por favor, introduce un enlace para analizar.');
      return;
    }

    // Basic URL validation. Allows for URLs without http protocol.
    const urlPattern = new RegExp('^(https?://)?([\\da-z.-]+)\\.([a-z.]{2,6})([/\\w .-]*)/?$');

    if (!urlPattern.test(url)) {
      this.error.set('El enlace introducido no parece ser una URL válida.');
      return;
    }

    await this.generate(url);
    this.manualUrlInput.set(''); 
  }

  async generate(url: string, title?: string) {
    this.isLoading.set(true);
    this.error.set(null);
    this.isOverloaded.set(false);
    this.generatedNews.set(null);
    this.streamingText.set('');

    try {
      // Simplified call: No tone or format needed anymore
      const stream = await this.geminiService.generateNewsContentStream(url, title);

      let accumulatedJson = '';
      for await (const chunk of stream) {
        accumulatedJson += chunk.text;
        this.streamingText.set(accumulatedJson);
      }

      const finalResult = this.geminiService.parseResponse(accumulatedJson);
      this.generatedNews.set(finalResult);

    } catch (err: any) {
      this.handleError(err);
    } finally {
      this.isLoading.set(false);
      this.streamingText.set('');
    }
  }

  private handleError(err: any) {
    console.error("Error detectado:", err);
    let errorMessage = '';

    try {
      // The error from the SDK might be a stringified JSON within another JSON.
      const outerError = JSON.parse(err.message || '{}');
      const innerError = JSON.parse(outerError?.error?.message || '{}');
      errorMessage = innerError?.error?.message || outerError?.error?.message || err.message;
    } catch {
      errorMessage = err.message || JSON.stringify(err);
    }

    if (errorMessage.includes('429') || errorMessage.includes('RESOURCE_EXHAUSTED') || errorMessage.includes('quota')) {
      this.isOverloaded.set(true);
      this.error.set('Límite de peticiones gratuitas alcanzado. La red está sobrecargada. Por favor, espera un momento antes de volver a intentarlo.');
    } else {
      this.error.set(errorMessage || 'Ocurrió un error al generar. Revisa la consola.');
    }
  }

  // --- Visualization Generation ---
  async visualizePromptHandler(news: NewsItem) {
    this.visualizationState.set('loading');
    this.visualizationText.set(null);

    try {
      const description = await this.geminiService.visualizePrompt(news.imagePrompt);
      this.visualizationText.set(description);
      this.visualizationState.set('success');
    } catch (err) {
      console.error('Failed to visualize prompt:', err);
      this.visualizationState.set('error');
      this.handleError(err);
    }
  }

  closeVisualization() {
    this.visualizationState.set('idle');
    this.visualizationText.set(null);
  }

  // --- UI and Utility ---
  copyToClipboard(text: string | undefined) {
    if (!text) return;
    navigator.clipboard.writeText(text);
  }
}

import { Injectable, signal } from '@angular/core';
import { GoogleGenAI } from '@google/genai';

@Injectable({
  providedIn: 'root'
})
export class GeminiService {
  private ai: GoogleGenAI | undefined;
  isConfigured = signal<boolean>(false);
  private pollingInterval: any = null;

  constructor() {
    this.configure();
  }

  private configure(): void {
    if (this.isConfigured()) return;

    let apiKey: string | undefined;

    // --- VERCEL / VITE STRATEGY ---
    // Accessing import.meta.env safely.
    // We cast to 'any' to avoid TypeScript errors with 'import.meta' in some environments.
    try {
      const env = (import.meta as any).env;

      // DEBUG: Check what Env vars are visible (Don't log full keys in real prod usually, but helpful here)
      console.log('Environment check:', { 
        hasImportMeta: !!import.meta, 
        hasEnv: !!env,
        viteKeyExists: env ? !!env.VITE_API_KEY : false 
      });

      if (env && env.VITE_API_KEY) {
        apiKey = env.VITE_API_KEY;
        this.logMaskedKey(apiKey, 'Vercel/Vite (import.meta.env)');
      }
    } catch (e) {
      console.warn('Error accessing import.meta.env:', e);
    }

    // --- AI STUDIO FALLBACK ---
    // If Vercel key is missing, we try the polling method for AI Studio preview
    if (!apiKey) {
      console.log('No Vercel key found. Checking AI Studio runtime injection...');
      this.checkAiStudioKey(); // Check once immediately
      // Keep polling ONLY if we haven't found a key yet
      if (!this.isConfigured()) {
        this.pollingInterval = setInterval(() => this.checkAiStudioKey(), 1000);
      }
    } else {
      this.initialize(apiKey);
    }
  }

  private logMaskedKey(key: string | undefined, source: string) {
    if (key && key.length > 4) {
      const masked = key.slice(-4);
      console.log(`API Key detected via ${source}: ************${masked}`);
    } else {
      console.log(`API Key detected via ${source}: (Invalid or Empty)`);
    }
  }

  private checkAiStudioKey(): void {
    // Legacy/Preview environment check
    const runtimeKey = (window as any).process?.env?.API_KEY;
    if (runtimeKey && !this.isConfigured()) {
      this.logMaskedKey(runtimeKey, 'AI Studio Runtime');
      this.initialize(runtimeKey);
    }
  }

  private initialize(apiKey: string): void {
    if (this.isConfigured()) return;

    if (apiKey && apiKey.length > 10) {
      try {
        this.ai = new GoogleGenAI({ apiKey: apiKey });
        this.isConfigured.set(true);

        // Stop polling if we were polling
        if (this.pollingInterval) {
          clearInterval(this.pollingInterval);
          this.pollingInterval = null;
        }

        console.log('Gemini Service configured successfully.');
      } catch (e) {
        console.error('CRITICAL: Failed to initialize GoogleGenAI.', e);
        this.isConfigured.set(false);
      }
    }
  }

  private getAiClient(): GoogleGenAI {
    if (!this.ai) {
      throw new Error('GeminiService is not configured. API Key is missing.');
    }
    return this.ai;
  }

  // MÉTODO LIGERO: Buscador de titulares
  async searchHeadlines(topics: string[]): Promise<any[]> {
    const modelId = 'gemini-2.5-flash';
    const topicsString = topics.length > 0 ? topics.join(', ') : 'Tecnología y Geopolítica Global';

