     if (jsonMatch) jsonString = jsonMatch[1];
     const clean = (str: string) => str.trim().replace(/,\s*([}\]])/g, '$1');

     try {
       return JSON.parse(clean(jsonString));
     } catch (e) {
       // Simple fallback extraction if JSON is broken
       const start = jsonString.indexOf('{');
       const end = jsonString.lastIndexOf('}');
       if (start !== -1 && end > start) {
         try { return JSON.parse(clean(jsonString.substring(start, end + 1))); } catch(e2) {}
       }
       const aStart = jsonString.indexOf('[');
       const aEnd = jsonString.lastIndexOf(']');
       if (aStart !== -1 && aEnd > aStart) {
          try { return JSON.parse(clean(jsonString.substring(aStart, aEnd + 1))); } catch(e2) {}
       }
       throw new Error('No se pudo extraer JSON válido.');
     }
  }
}

