        "title": "Título",
        "sourceUrl": "URL",
        "whatsappContent": "Texto del análisis con saltos de línea \\n",
        "imagePrompt": "Prompt visual en Inglés",
        "videoPrompt": "Prompt de video en Inglés"
      }

      Usa Google Search para leer la URL. Idioma: Español.
    `;

    const userPrompt = title
      ? `Analiza: "${title}" (${url}). Genera análisis para WhatsApp.`
      : `Analiza la URL: ${url}. Genera análisis para WhatsApp.`;

    const client = this.getAiClient();
    return client.models.generateContentStream({
      model: modelId,
      contents: userPrompt,
      config: {
        systemInstruction,
        temperature: 0.7,
        tools: [{ googleSearch: {} }]
      }
    });
  }

  // Visualizador
  async visualizePrompt(prompt: string): Promise<string> {
    const modelId = 'gemini-2.5-flash';
    const systemInstruction = `Describe la escena visualmente en español basada en el prompt.`;

    try {
      const client = this.getAiClient();
      const response = await client.models.generateContent({
        model: modelId,
        contents: `Describe: "${prompt}"`,
        config: { systemInstruction }
      });
      return response.text;
    } catch (error) {
      console.error('Error visualizando:', error);
      throw error;
    }
  }

  // Utility JSON Parser
  parseResponse(text: string | undefined): any {
     if (!text) throw new Error('Sin texto generado.');
     let jsonString = text;
     const jsonMatch = text.match(/```json\s*([\s\S]*?)\s*```/) || text.match(/```\s*([\s\S]*?)\s*```/);
     if (jsonMatch) jsonString = jsonMatch[1];
     const clean = (str: string) => str.trim().replace(/,\s*([}\]])/g, '$1');

     try {
       return JSON.parse(clean(jsonString));
     } catch (e) {
       // Simple fallback extraction if JSON is broken
       const start = jsonString.indexOf('{');
       const end = jsonString.lastIndexOf('}');
       if (start !== -1 && end > start) {
         try { return JSON.parse(clean(jsonString.substring(start, end + 1))); } catch(e2) {}
       }
       const aStart = jsonString.indexOf('[');
       const aEnd = jsonString.lastIndexOf(']');
       if (aStart !== -1 && aEnd > aStart) {
          try { return JSON.parse(clean(jsonString.substring(aStart, aEnd + 1))); } catch(e2) {}
       }
       throw new Error('No se pudo extraer JSON válido.');
     }
  }
}

