import { Injectable, signal } from '@angular/core';
import { GoogleGenAI } from '@google/genai';

@Injectable({
  providedIn: 'root'
})
export class GeminiService {
  private ai: GoogleGenAI | undefined;
  isConfigured = signal<boolean>(false);
  private configPollInterval: any;

  constructor() {
    this.startConfigurationPolling();
  }

  private startConfigurationPolling(): void {
    const attemptConfig = () => {
      if (this.isConfigured()) return true;

      // Check all possible locations for API KEY
      const key = 
        (window as any).process?.env?.API_KEY || 
        (import.meta as any).env?.VITE_API_KEY || 
        (window as any).__API_KEY__;

      if (key && typeof key === 'string' && key.length > 10 && !key.startsWith('%')) {
        this.initialize(key);
        return true;
      }
      return false;
    };

    if (!attemptConfig()) {
      this.configPollInterval = setInterval(() => {
        if (attemptConfig()) {
          clearInterval(this.configPollInterval);
        }
      }, 500);
    }
  }

  private initialize(apiKey: string): void {
    try {
      this.ai = new GoogleGenAI({ apiKey });
      this.isConfigured.set(true);
      console.log('Gemini Service: Conectado con éxito.');
    } catch (e) {
      console.error('Gemini Service: Error de inicialización:', e);
    }
  }

  private getClient(): GoogleGenAI {
    if (!this.ai) throw new Error('API Key no configurada.');
    return this.ai;
  }

  async searchHeadlines(topics: string[]): Promise<any[]> {
    const model = 'gemini-2.5-flash';
    const query = topics.join(', ') || 'Noticias internacionales de hoy';

    // Rule: googleSearch tool MUST NOT have responseMimeType: "application/json"
    const prompt = `Busca las 6 noticias más importantes y recientes sobre: ${query}. 
    Devuelve los resultados en un formato de lista simple: Título | Fuente | URL. 
    Traduce todo al español.`;

    try {
      const response = await this.getClient().models.generateContent({
        model,
        contents: prompt,
        config: {
          tools: [{ googleSearch: {} }],
          temperature: 0.2
        }
      });

      // Parse text response manually since we can't use JSON schema with search
      return this.manualParseHeadlines(response.text);
    } catch (error) {
      console.error('Error en búsqueda:', error);
      throw error;
    }
  }

  private manualParseHeadlines(text: string): any[] {
    // Basic logic to extract items if they follow the "Title | Source | URL" pattern
    // If it fails, we ask the model to re-format it without search tools
    const lines = text.split('\n').filter(l => l.trim().length > 10);
    return lines.map(line => ({
      title: line.replace(/^[0-9*.\s-]+/, '').split('|')[0]?.trim() || line,
      source: line.split('|')[1]?.trim() || 'Fuente Web',
      url: line.match(/https?:\/\/[^\s)]+/)?.[0] || '#'
    })).slice(0, 6);
  }

  async generateAnalysisStream(url: string, title?: string) {
    const model = 'gemini-2.5-flash';

    const systemInstruction = `Eres un analista experto para un grupo exclusivo de WhatsApp.
    Analiza la URL proporcionada y genera un resumen estructurado exactamente en 3 párrafos cortos:
    1. 📰 *EL HECHO*: Qué pasó exactamente (datos duros).
    2. 💡 *EL CONTEXTO*: Por qué importa y antecedentes clave.
    3. 🚀 *LA PROYECCIÓN*: Qué podemos esperar a futuro.

    Usa emojis estratégicos. Tono: Profesional pero directo. Máximo 150 palabras total.
    Usa Google Search para leer la URL. Idioma: Español.`;

    const userPrompt = `Analiza este enlace: ${url} ${title ? `(Titular: ${title})` : ''}`;

    return this.getClient().models.generateContentStream({
      model,
      contents: userPrompt,
      config: {
        systemInstruction,
        tools: [{ googleSearch: {} }],
        temperature: 0.7
      }
    });
  }

  // Visualizer tool
  async visualize(prompt: string): Promise<string> {
    const response = await this.getClient().models.generateContent({
      model: 'gemini-2.5-flash',
      contents: `Describe visualmente esta escena de forma cinemática y detallada en español: "${prompt}"`,
    });
    return response.text;
  }
}

import { Component, signal, inject, ChangeDetectionStrategy } from '@angular/core';
import { CommonModule } from '@angular/common';
import { GeminiService } from './services/gemini.service';
import { MatrixRainComponent } from './components/matrix-rain.component';

@Component({
  selector: 'app-root',
  standalone: true,
  imports: [CommonModule, MatrixRainComponent],
  templateUrl: './app.component.html',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class AppComponent {
  private geminiService = inject(GeminiService);
  isConfigured = this.geminiService.isConfigured;

  // UI State
  isBooting = signal(true);
  isLoading = signal(false);
  isSearching = signal(false);
  error = signal<string | null>(null);

  // Data State
  headlines = signal<any[]>([]);
  analysisResult = signal<any | null>(null);
  streamingText = signal('');
  manualUrl = signal('');

  topics = [
    'Última Hora', 'Tecnología', 'México', 'Geopolítica', 'IA', 'Economía', 'Cripto'
  ];
  selectedTopics = signal<Set<string>>(new Set(['Última Hora']));

  toggleTopic(topic: string) {
    const current = new Set(this.selectedTopics());
    current.has(topic) ? current.delete(topic) : current.add(topic);
    this.selectedTopics.set(current);
  }

  async fetchHeadlines() {
    if (this.selectedTopics().size === 0) return;
    this.isSearching.set(true);
    this.error.set(null);
    try {
      const results = await this.geminiService.searchHeadlines(Array.from(this.selectedTopics()));
      this.headlines.set(results);
    } catch (e: any) {
      this.error.set('No se pudieron obtener titulares. Intenta de nuevo.');
    } finally {
      this.isSearching.set(false);
    }
  }

  async generateAnalysis(url: string, title?: string) {
    this.isLoading.set(true);
    this.error.set(null);
    this.streamingText.set('');
    this.analysisResult.set(null);

    try {
      const stream = await this.geminiService.generateAnalysisStream(url, title);
      let fullText = '';

      for await (const chunk of stream) {
        fullText += chunk.text;
        this.streamingText.set(fullText);
      }

      this.analysisResult.set({
        title: title || 'Análisis de Noticia',
        url,
        content: fullText
      });
    } catch (e: any) {
      this.error.set('Error generando el análisis. Verifica tu conexión.');
    } finally {
      this.isLoading.set(false);
    }
  }

  copyToClipboard(text: string) {
    navigator.clipboard.writeText(text);
    // Simple toast could be added here
  }

  onUrlInput(e: Event) {
    this.manualUrl.set((e.target as HTMLInputElement).value);
  }
}

