        </div>
        <div class="space-y-2 font-mono text-sm tracking-tighter">
          <p class="text-teal-500 animate-pulse">{{ currentLog() }}</p>
          <div class="w-48 h-1 bg-neutral-900 rounded-full mx-auto overflow-hidden">
            <div class="h-full bg-teal-500 transition-all duration-500" [style.width.%]="progress()"></div>
          </div>
        </div>
      </div>
    </div>
  `,
  styles: [`
    .matrix-col {
      animation: matrix-fall linear infinite;
      transform: translateY(-100%);
    }
    @keyframes matrix-fall {
      to { transform: translateY(100vh); }
    }
  `],
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class MatrixRainComponent implements AfterViewInit {
  bootComplete = output<void>();

  chars = '01ｱｲｳｴｵｶｷｸｹｺｻｼｽｾｿﾀﾁﾂﾃﾄﾅﾆﾇﾈﾉﾊﾋﾌﾍﾎﾏﾐﾑﾒﾓﾔﾕﾖﾗﾘﾙﾚﾛﾜﾝ'.split('');
  columns = Array(30).fill(0);
  durations = Array(30).fill(0).map(() => Math.random() * 5 + 3);
  delays = Array(30).fill(0).map(() => Math.random() * -10);

  currentLog = signal('Iniciando sistemas...');
  progress = signal(0);

  private logs = [
    'Estableciendo conexión...',
    'Inyectando variables de entorno...',
    'Inicializando Gemini 2.5 Flash...',
    'Cargando protocolos editoriales...',
    'Acceso concedido.'
  ];

  ngAfterViewInit() {
    this.startSequence();
  }

  private async startSequence() {
    for (let i = 0; i < this.logs.length; i++) {
      this.currentLog.set(this.logs[i]);
      this.progress.set((i + 1) * (100 / this.logs.length));
      await new Promise(r => setTimeout(r, 600));
    }
    await new Promise(r => setTimeout(r, 400));
    this.bootComplete.emit();
  }
}

